// Com todas=N a API retorna apenas registros não integrados,
// sem necessidade de filtro por data.
const cfg = $input.first().json;

return [{
  json: {
    ...cfg,
    chunk_dtini_iso: null,
    chunk_dtfim_iso: null,
    is_diario: true
  }
}];

const cfg = $input.first().json;
const token = $('POST /auth (Login)').first().json.token;

if (!token) {
  throw new Error('Token não encontrado no retorno do /auth');
}

// Sem filtro de data — todas=N retorna apenas não integrados
const url = `${cfg.url_base}/Transacoes?todas=N`;

return [{
  json: {
    ...cfg,
    token,
    url_final: url,
    bearer_header: `Bearer ${token}`,
    chunk_inicio_ts: Date.now()
  }
}];

const raw = $input.first().json;
const transacoes = raw.Transacoes || [];

if (transacoes.length === 0) return [];

// 1. MAPEAMENTO ATUALIZADO (Adicionado Garagem e CentroCusto)
const mapa = {
  Transacao: 'transacao',
  DataTransacao: 'data_transacao',
  Hodometro: 'hodometro',
  Valor: 'valor',
  Litragem: 'litragem',
  CodCombustivel: 'cod_combustivel',
  NomeCombustivel: 'nome_combustivel',
  Servico: 'servico',
  TipoAbastecimento: 'tipo_abastecimento',
  CodigoTanque: 'codigo_tanque',
  NomeTanque: 'nome_tanque',
  CodigoBomba: 'codigo_bomba',
  NomeBomba: 'nome_bomba',
  RazaoSocialPosto: 'razao_social_posto',
  NomeFantasiaPosto: 'nome_fantasia_posto',
  CNPJPosto: 'cnpj_posto',
  CidadePosto: 'cidade_posto',
  UFPosto: 'uf_posto',
  CartaoMascarado: 'cartao_mascarado',
  Motorista: 'motorista',
  MatriculaMotorista: 'matricula_motorista',
  CPFMotorista: 'cpf_motorista',
  Placa: 'placa',
  ModeloVeiculo: 'modelo_veiculo',
  AnoVeiculo: 'ano_veiculo',
  MatriculaVeiculo: 'matricula_veiculo',
  MarcaVeiculo: 'marca_veiculo',
  CorVeiculo: 'cor_veiculo',
  TransacaoEstornada: 'transacao_estornada',
  CNPJCliente: 'cnpj_cliente',
  Garagem: 'garagem',           // <--- ADICIONADO
  CentroCusto: 'centro_custo'   // <--- ADICIONADO
};

const colunas = Object.values(mapa);
const colunasNumericas = new Set(['valor', 'litragem']);

const seen = new Map();
for (const tx of transacoes) {
  const obj = {};
  for (const [api, db] of Object.entries(mapa)) {
    obj[db] = tx[api] !== undefined ? tx[api] : null;
  }
  seen.set(obj.transacao, obj);
}
const dedup = Array.from(seen.values());

const CHUNK = 500;
const chunks = [];
for (let i = 0; i < dedup.length; i += CHUNK) chunks.push(dedup.slice(i, i + CHUNK));

const escapar = (v, col) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (colunasNumericas.has(col)) {
    const n = parseFloat(String(v).replace(',', '.'));
    return isNaN(n) ? 'NULL' : n;
  }
  return `'${String(v).replace(/'/g, "''")}'`;
};

const conflictCol = 'transacao';
const updateSet = colunas
  .filter(c => c !== conflictCol)
  .map(c => `"${c}" = EXCLUDED."${c}"`)
  .join(',\n  ');

const result = [];
for (const chunk of chunks) {
  const values = chunk.map(row => {
    const vals = colunas.map(c => escapar(row[c], c));
    return `(${vals.join(', ')}, (NOW() AT TIME ZONE 'America/Sao_Paulo'), NULL)`;
  }).join(',\n');

  const sql = `INSERT INTO torre.integration_truckpag_transacoes (
  ${colunas.map(c => `"${c}"`).join(', ')},
  inserido,
  atualizado
)
VALUES ${values}
ON CONFLICT ("${conflictCol}") DO UPDATE SET
  ${updateSet},
  atualizado = (NOW() AT TIME ZONE 'America/Sao_Paulo');`.trim();

  result.push({ json: { sql, qtd_registros: chunk.length } });
}

return result;

// Acumula estatísticas do run via Static Data (persiste entre execuções do loop)
const sd = $getWorkflowStaticData('global');
const cfg = $('Loop Over Chunks').item.json;

// Inicializa na primeira iteração do run (detecta pela chave run_inicio_ts)
if (!sd.run_inicio_ts || sd.run_inicio_ts !== cfg.run_inicio_ts) {
  sd.run_inicio_ts  = cfg.run_inicio_ts;
  sd.chunks_ok      = 0;
  sd.chunks_vazio   = 0;
  sd.chunks_erro    = 0;
  sd.total_registros = 0;
  sd.run_inicio_iso = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
}

// Determina o status desta iteração via input (passado pelo nó anterior)
const status = $input.first().json._acumula_status ?? 'sucesso';
const qtd    = $input.first().json._acumula_qtd    ?? 0;

if (status === 'sucesso') {
  sd.chunks_ok++;
  sd.total_registros += qtd;
} else if (status === 'vazio') {
  sd.chunks_vazio++;
} else if (status === 'erro') {
  sd.chunks_erro++;
}

// Passa os dados acumulados adiante
return [{
  json: {
    ...$input.first().json,
    stats: {
      chunks_ok:        sd.chunks_ok,
      chunks_vazio:     sd.chunks_vazio,
      chunks_erro:      sd.chunks_erro,
      total_registros:  sd.total_registros,
      run_inicio_iso:   sd.run_inicio_iso
    }
  }
}];
